import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    M=8 if any(g[r][c]==8 for r,c in cells) or any(g[r][c]==8 for r in range(h) for c in range(w)) else 1
    marker=M
    for r in range(r0,r1+1):
        left=any(g[r][c]==marker for c in range(0,c0))
        right=any(g[r][c]==marker for c in range(c1+1,w))
        if not left:
            for c in range(0,c0): out[r][c]=2
        if not right:
            for c in range(c1+1,w): out[r][c]=2
    for c in range(c0,c1+1):
        up=any(g[r][c]==marker for r in range(0,r0))
        dn=any(g[r][c]==marker for r in range(r1+1,h))
        if not up:
            for r in range(0,r0): out[r][c]=2
        if not dn:
            for r in range(r1+1,h): out[r][c]=2
    return out
print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])

out=transform(G['Test input'])
for r in out: print(' '.join(map(str,r)))
print(json.dumps(out))
